import React, { useState, useEffect } from 'react';
import './Admin.css';  // Importing the CSS file for styling

const ForumForm = ({ onSubmit }) => {
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [categories, setCategories] = useState([]);
    const [selectedCategory, setSelectedCategory] = useState('');
    const [banner, setBanner] = useState('');
    const [error, setError] = useState(null);
    const [success, setSuccess] = useState(null);

    // Fetch categories when the component mounts
    useEffect(() => {
        fetch('http://localhost:8741/api/category/categories') // Replace with your actual backend endpoint
            .then(response => response.json())
            .then(data => {
                setCategories(data);
                setSelectedCategory(data.length > 0 ? data[0].id : '');
            })
            .catch(error => {
                console.error('Error fetching categories:', error);
                setError("Failed to load categories.");
            });
    }, []);

    const handleSubmit = (e) => {
        e.preventDefault();

        if (!name || !description || !selectedCategory) {
            setError("All fields are required.");
            return;
        }

        onSubmit({ name, description, category_id: selectedCategory, banner })
            .then(() => {
                setSuccess("Forum created successfully!");
                setName('');
                setDescription('');
                setSelectedCategory(categories.length > 0 ? categories[0].id : '');
                setBanner('');
                setError(null);
            })
            .catch((err) => {
                setError("An error occurred while creating the forum.");
                setSuccess(null);
            });
    };

    return (
        <form onSubmit={handleSubmit} className="admin-panel-form">
            <h2>Create a New Forum</h2>

            {error && <div className="error-message">{error}</div>}
            {success && <div className="success-message">{success}</div>}

            <label>
                Name:
                <input 
                    type="text" 
                    value={name} 
                    onChange={(e) => setName(e.target.value)} 
                    required 
                />
            </label>

            <label>
                Description:
                <textarea 
                    value={description} 
                    onChange={(e) => setDescription(e.target.value)} 
                    required 
                />
            </label>

            <label>
                Category:
                <select 
                    value={selectedCategory} 
                    onChange={(e) => setSelectedCategory(e.target.value)} 
                    required
                >
                    {categories.map(category => (
                        <option key={category.id} value={category.id}>
                            {category.name}
                        </option>
                    ))}
                </select>
            </label>

            <label>
                Banner URL:
                <input 
                    type="text" 
                    value={banner} 
                    onChange={(e) => setBanner(e.target.value)} 
                />
            </label>

            <button type="submit">Create Forum</button>
        </form>
    );
};

export default ForumForm;
